import{_ as a,o as n,a as p,b as c}from"./app.CttuQoSk.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"asc_copy_l12bt_arch_3510","link":"/api/SIMD-API/c_api/cube_datamove/asc_copy_l12bt/asc_copy_l12bt_arch_3510"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/asc_copy_l12bt/asc_copy_l12bt_arch_3510.md","filePath":"api/SIMD-API/c_api/cube_datamove/asc_copy_l12bt/asc_copy_l12bt_arch_3510.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":3,"title":"高维切分搬运模式","slug":"高维切分搬运模式","link":"#高维切分搬运模式"},{"level":4,"title":"dtype支持的数据类型","slug":"dtype支持的数据类型","link":"#dtype支持的数据类型"},{"level":4,"title":"函数原型典型示例","slug":"函数原型典型示例","link":"#函数原型典型示例"},{"level":3,"title":"连续数据搬运模式","slug":"连续数据搬运模式","link":"#连续数据搬运模式"},{"level":4,"title":"dtype支持的数据类型","slug":"dtype支持的数据类型-1","link":"#dtype支持的数据类型-1"},{"level":4,"title":"函数原型典型示例","slug":"函数原型典型示例-1","link":"#函数原型典型示例-1"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":3,"title":"通用约束","slug":"通用约束","link":"#通用约束"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788916090000}'),l={name:"api/SIMD-API/c_api/cube_datamove/asc_copy_l12bt/asc_copy_l12bt_arch_3510.md"};function t(e,s,d,o,i,_){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>asc_copy_l12bt</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;c_api/cube_datamove/cube_datamove.h&quot;</code>。</p><p>将L1 Buffer中的偏置数据搬运到BiasTable Buffer，供矩阵计算单元（Mmad）作为bias输入读取。支持源操作数为<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>float</code>类型搬运，其中搬运过程对于<code>half</code>、<code>bfloat16_t</code>会进行随路格式转换后写入BiasTable Buffer：<code>bfloat16_t</code>自动转换为<code>float</code>；<code>half</code>在开启转换即<code>conv_control</code>设置为1时转换为<code>float</code>，未开启转换即<code>conv_control</code>设置为0时每个<code>half</code>元素仅扩展为32 bit（高16 bit为占位数据）。</p><p>本接口提供两种参数列表完全不同的功能模式，用户按需选择对应重载：</p><ul><li><strong>高维切分搬运</strong>：通过配置数据块个数、单个数据块长度、源/目间隔等搬运参数实现连续与非连续搬运。</li><li><strong>连续数据搬运</strong>：仅指定<code>size</code>，按照一个连续数据块搬运，源/目间隔均为0。</li></ul><p>本接口仅在AIC上执行有效。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><h3 id="高维切分搬运模式">高维切分搬运模式<a class="header-anchor" href="#高维切分搬运模式">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 占位符形式</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12bt</span><span class="p">(</span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__cbuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">conv_control</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">n_burst</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">len_burst</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">source_gap</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_gap</span><span class="p">)</span>
</code></pre></div><h4 id="dtype支持的数据类型">dtype支持的数据类型<a class="header-anchor" href="#dtype支持的数据类型">​</a></h4><p>dtype支持的数据类型为<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>float</code>。</p><h4 id="函数原型典型示例">函数原型典型示例<a class="header-anchor" href="#函数原型典型示例">​</a></h4><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 示例：bfloat16_t类型的高维切分搬运。</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12bt</span><span class="p">(</span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__cbuf__</span><span class="w"> </span><span class="n">bfloat16_t</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">conv_control</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">n_burst</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">len_burst</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">source_gap</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_gap</span><span class="p">)</span>
</code></pre></div><h3 id="连续数据搬运模式">连续数据搬运模式<a class="header-anchor" href="#连续数据搬运模式">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 占位符形式</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12bt</span><span class="p">(</span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__cbuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">size</span><span class="p">)</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12bt_sync</span><span class="p">(</span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                           </span><span class="n">__cbuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                           </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">size</span><span class="p">)</span>
</code></pre></div><h4 id="dtype支持的数据类型-1">dtype支持的数据类型<a class="header-anchor" href="#dtype支持的数据类型-1">​</a></h4><p>dtype支持的数据类型为<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>float</code>。</p><h4 id="函数原型典型示例-1">函数原型典型示例<a class="header-anchor" href="#函数原型典型示例-1">​</a></h4><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 示例：float类型的连续数据搬运。</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12bt</span><span class="p">(</span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__cbuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">size</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，存储位置为BiasTable Buffer。目的地址需64字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，存储位置为L1 Buffer。源地址需32字节对齐。</td></tr><tr><td>conv_control</td><td>输入</td><td>源操作数为<code>half</code>类型时，是否开启随路格式转换。<br>  • <code>0</code>：不开启转换，每个<code>half</code>元素扩展为32 bit（高16 bit为占位数据）后写入BT；<br>  • <code>1</code>：开启转换，每个<code>half</code>元素转换为<code>float</code>后写入BT。仅dtype为<code>half</code>时可设置，其他dtype需设置为0。</td></tr><tr><td>n_burst</td><td>输入</td><td>待搬运的连续数据块个数。取值范围 [1, 4095]。</td></tr><tr><td>len_burst</td><td>输入</td><td>每个连续数据块的长度，单位32字节。取值范围 [1, 65535]。dtype为<code>float</code>或<code>int32_t</code>时需2对齐（即取值为偶数），否则触发异常。</td></tr><tr><td>source_gap</td><td>输入</td><td>源端（L1 Buffer）相邻两次搬运之间的间隔，单位32字节，从上一次搬运结束位置到下一次搬运起始位置。取值范围 [0, 65535]。<code>n_burst=1</code>时无意义，置0即可。</td></tr><tr><td>dst_gap</td><td>输入</td><td>目的端（BiasTable Buffer）相邻两次搬运之间的间隔，单位32字节，从上一次搬运结束位置到下一次搬运起始位置。取值范围 [0, 65535]。<code>n_burst=1</code>时无意义，置0即可。dtype为<code>float</code>或<code>int32_t</code>时需2对齐（即取值为偶数），否则触发异常。</td></tr><tr><td>size</td><td>输入</td><td>搬运数据总大小，单位字节。<br><strong>注：size需要32字节对齐，若未对齐，搬运量会向下取整到32字节对齐。</strong></td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_MTE1</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><h3 id="通用约束">通用约束<a class="header-anchor" href="#通用约束">​</a></h3><ul><li>本接口非AIC调用直接返回。</li><li>dst起始地址需64字节对齐（BiasTable Buffer对齐要求），src起始地址需32字节对齐（L1 Buffer对齐要求），否则触发异常。</li><li>BiasTable Buffer容量上限4KB，dst偏移与搬运大小之和不可越界，否则触发写溢出异常。</li><li>L1 Buffer容量上限512KB，src偏移与搬运大小之和不可越界，否则触发读异常。</li><li>如果本指令与其他指令存在目的地址重叠，需要插入同步指令（<a href="../../sync/asc_sync_notify.html">asc_sync_notify</a>和<a href="../../sync/asc_sync_wait.html">asc_sync_wait</a>），保证多个指令串行化，防止出现异常数据。</li><li>n_burst为0时不执行搬运，本接口被视为NOP（空操作）。</li><li>dtype为<code>float</code>或<code>int32_t</code>时，len_burst与dst_gap均必须2对齐（即取值为偶数），size/32需为偶数，否则触发搬运异常。</li><li>conv_control开启（非0）时dtype必须为<code>half</code>，否则触发搬运异常，传入非0/1的值仅最低位生效（如2等价于0即转换关闭、3等价于1即转换开启）。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>将代码保存为<code>examples.asc</code>后，可通过<code>bisheng</code>命令编译运行，其中<code>--npu-arch</code>参数需根据实际产品型号指定对应的NPU架构，具体产品与NPU架构的映射关系请参考<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch"><code>__NPU_ARCH__</code></a>。</p><div data-filter="950"><p>以Ascend 950PR/Ascend 950DT产品（对应NPU架构为<code>dav-3510</code>）为例，编译运行命令如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>bisheng<span class="w"> </span>examples.asc<span class="w"> </span>-o<span class="w"> </span>main<span class="w"> </span>--npu-arch<span class="o">=</span>dav-3510<span class="w"> </span><span class="o">&amp;&amp;</span><span class="w"> </span>./main
</code></pre></div></div><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;cstdint&gt;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;cstdio&gt;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;acl/acl.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;c_api/asc_simd.h&quot;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">M</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">,</span><span class="w"> </span><span class="n">N</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">,</span><span class="w"> </span><span class="n">K</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">BYTES</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">N</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">);</span>

<span class="n">__global__</span><span class="w"> </span><span class="n">__cube__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CopyL12btKernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc_init</span><span class="p">();</span>
<span class="w">    </span><span class="n">__cbuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">l1</span><span class="p">[</span><span class="n">N</span><span class="p">];</span>
<span class="w">    </span><span class="n">asc_copy_gm2l1</span><span class="p">(</span><span class="n">l1</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">BYTES</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE1</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE1</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_copy_l12bt</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">l1</span><span class="p">,</span><span class="w"> </span><span class="n">BYTES</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_pipe</span><span class="p">(</span><span class="n">PIPE_ALL</span><span class="p">);</span>
<span class="p">}</span>

<span class="kt">int</span><span class="w"> </span><span class="n">main</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">aclInit</span><span class="p">(</span><span class="nb">nullptr</span><span class="p">);</span><span class="w"> </span><span class="n">aclrtSetDevice</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="w">    </span><span class="n">aclrtMalloc</span><span class="p">(</span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="kt">void</span><span class="o">**&gt;</span><span class="p">(</span><span class="o">&amp;</span><span class="n">input</span><span class="p">),</span><span class="w"> </span><span class="n">BYTES</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEM_MALLOC_HUGE_FIRST</span><span class="p">);</span>
<span class="w">    </span><span class="n">CopyL12btKernel</span><span class="o">&lt;&lt;&lt;</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">input</span><span class="p">);</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">aclError</span><span class="w"> </span><span class="n">ret</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">aclrtSynchronizeDevice</span><span class="p">();</span>
<span class="w">    </span><span class="n">std</span><span class="o">::</span><span class="n">printf</span><span class="p">(</span><span class="s">&quot;M=%u N=%u K=%u asc_copy_l12bt=%s</span><span class="se">\\n</span><span class="s">&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">M</span><span class="p">,</span><span class="w"> </span><span class="n">N</span><span class="p">,</span><span class="w"> </span><span class="n">K</span><span class="p">,</span>
<span class="w">        </span><span class="n">ret</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">ACL_SUCCESS</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="s">&quot;PASS&quot;</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="s">&quot;FAIL&quot;</span><span class="p">);</span>
<span class="w">    </span><span class="n">aclrtFree</span><span class="p">(</span><span class="n">input</span><span class="p">);</span><span class="w"> </span><span class="n">aclrtResetDevice</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w"> </span><span class="n">aclFinalize</span><span class="p">();</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">ret</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">ACL_SUCCESS</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="mi">0</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const w=a(l,[["render",t]]);export{r as __pageData,w as default};
